import React, { useMemo } from 'react';
import {
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import type { WidgetProps, ChartDataPoint, FieldMappingOverride } from '../types';
import { extractChartContract } from '../types';
import { useWidgetFetch } from '../hooks/useWidgetFetch';
import { aggregateChartData } from '../utils/aggregateChartData';
import { WidgetDataGuard } from '../components/WidgetDataGuard';
import { resolveChartFields, resolveLabel } from '../utils/resolveChartFields';

import { DEFAULT_CHART_COLORS } from '../utils/chartColors';

const ChartDonut: React.FC<WidgetProps> = ({ definition, period, preference }) => {
  const { data, loading, error } = useWidgetFetch<ChartDataPoint[]>(
    definition.widget_id,
    period,
    definition.refresh_policy,
    definition.field_mapping?.rename
  );

  const { chartData, valueKey, categoryField, valueLabel } = useMemo(() => {
    if (!data || data.length === 0) return { chartData: [], valueKey: 'value', categoryField: 'name', valueLabel: 'value' };
    const raw = data as Record<string, unknown>[];
    const userOverride = preference.config_json?.fieldMapping as FieldMappingOverride | undefined;
    const { categoryField, valueFields } = resolveChartFields(definition.config_schema, raw, userOverride, definition.field_mapping);
    const mergedAliases = { ...(definition.field_mapping?.aliases ?? {}), ...(userOverride?.aliases ?? {}) };
    const contract = extractChartContract(definition.config_schema);

    if (valueFields.length === 1) {
      const processed = aggregateChartData(raw, categoryField, valueFields, contract?.aggregation);
      return { chartData: processed, valueKey: valueFields[0], categoryField, valueLabel: resolveLabel(valueFields[0], mergedAliases) };
    }

    // Donut solo muestra 1 valor. Si hay 2+ (no debería pasar si getCompatibleTypes
    // filtró correctamente), suma como fallback defensivo.
    const merged = raw.map(row => {
      const total = valueFields.reduce((sum, k) => {
        const v = row[k];
        return sum + (typeof v === 'number' ? v : 0);
      }, 0);
      return { ...row, total };
    });
    const processed = aggregateChartData(merged, categoryField, ['total'], contract?.aggregation);
    return { chartData: processed, valueKey: 'total', categoryField, valueLabel: 'Total' };
  }, [data, definition.config_schema, definition.field_mapping, preference.config_json]);

  return (
    <WidgetDataGuard loading={loading} error={error} data={data}>
    <div className="w-full h-full p-4">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie data={chartData} innerRadius="60%" outerRadius="80%" paddingAngle={2} dataKey={valueKey} nameKey={categoryField}>
            {chartData.map((_, index) => (
              <Cell key={`cell-${index}`} fill={DEFAULT_CHART_COLORS[index % DEFAULT_CHART_COLORS.length]} />
            ))}
          </Pie>
          <Tooltip
            contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
            formatter={(value) => [value, valueLabel]}
          />
          <Legend verticalAlign="middle" align="right" layout="vertical" wrapperStyle={{ right: 20 }} />
        </PieChart>
      </ResponsiveContainer>
    </div>
    </WidgetDataGuard>
  );
};

export default ChartDonut;
